            _ = bun.assert((bun.strings.indexOfChar(text, 47) == null));
},
else => {

},
}
            const payload = (switch (self) {
.text => |t| t,
.param => |t| t,
.catch_all_optional => |t| t,
.catch_all => |t| t,
.group => |t| t,
