.text => |p| bun.strings.eql(p, b.text),
.param => |p| bun.strings.eql(p, b.param),
.catch_all_optional => |p| bun.strings.eql(p, b.catch_all_optional),
.catch_all => |p| bun.strings.eql(p, b.catch_all),
.group => |p| bun.strings.eql(p, b.group),
