.text => |text| {
_ = try writer.print("/{s}", .{ text });
},
.param => |param_name| {
_ = try writer.print("/:{s}", .{ param_name });
},
.group => |label| {
_ = try writer.print("/({s})", .{ label });
},
.catch_all => |param_name| {
_ = try writer.print("/:*{s}", .{ param_name });
},
.catch_all_optional => |param_name| {
